import React, { useEffect, useState } from 'react';
import axios from 'axios';

const Cases = () => {
  const [cases, setCases] = useState([]);

  useEffect(() => {
    const fetchCases = async () => {
      try {
        const response = await axios.get('/api/cases');
        setCases(response.data);
      } catch (error) {
        console.error('Error fetching cases:', error);
      }
    };

    fetchCases();
  }, []);

  return (
    <div className="pg" id="page-cases">
      <div className="sec">
        <div style={{ textAlign: 'center', maxWidth: '600px', margin: '0 auto 3rem' }}>
          <span className="lbl reveal">Case Studies</span>
          <h1 className="dp reveal d1" style={{ marginTop: '.5rem' }}>
            Real results.<br />
            <span className="gr">Real businesses.</span>
          </h1>
          <p className="blg reveal d2" style={{ marginTop: '.9rem' }}>
            See how we've helped businesses transform their operations with AI.
          </p>
        </div>

        {cases.length > 0 ? (
          <div className="crows">
            {cases.map((caseStudy, index) => (
              <div key={index} className="crow">
                <div className="cl">
                  <div className="ctag">{caseStudy.category}</div>
                  <div className="cclient">{caseStudy.client}</div>
                  <div className={`cstat ${caseStudy.status === 'live' ? 'live' : ''}`}>
                    {caseStudy.status === 'live' ? 'Live' : 'Coming Soon'}
                  </div>
                </div>
                <div className="cr">
                  <div className="ctit">{caseStudy.title}</div>
                  <p className="cdesc">{caseStudy.description}</p>
                  <div className="cnums">
                    <div className="cnum">{caseStudy.result1_number}<span className="cnl">{caseStudy.result1_label}</span></div>
                    <div className="cnum">{caseStudy.result2_number}<span className="cnl">{caseStudy.result2_label}</span></div>
                  </div>
                  <div className="ctools">
                    {caseStudy.tools && caseStudy.tools.split(',').map((tool, i) => (
                      <span key={i} className="ctool">{tool.trim()}</span>
                    ))}
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div style={{ textAlign: 'center', padding: '4rem', color: 'var(--s)' }}>
            Case studies will be loaded from the database...
          </div>
        )}
      </div>
    </div>
  );
};

export default Cases;
